!function(t){function a(a){for(var r,n,p=a[0],o=a[1],u=a[2],s=0,g=[];s<p.length;s++)n=p[s],Object.prototype.hasOwnProperty.call(e,n)&&e[n]&&g.push(e[n][0]),e[n]=0;for(r in o)Object.prototype.hasOwnProperty.call(o,r)&&(t[r]=o[r]);for(c&&c(a);g.length;)g.shift()();return m.push.apply(m,u||[]),i()}function i(){for(var t,a=0;a<m.length;a++){for(var i,n=m[a],p=!0,o=1;o<n.length;o++)i=n[o],0!==e[i]&&(p=!1);p&&(m.splice(a--,1),t=r(r.s=n[0]))}return t}function r(a){if(n[a])return n[a].exports;var i=n[a]={i:a,l:!1,exports:{}};return t[a].call(i.exports,i,i.exports,r),i.l=!0,i.exports}var n={},e={14:0},m=[];r.m=t,r.c=n,r.d=function(t,a,i){r.o(t,a)||Object.defineProperty(t,a,{enumerable:!0,get:i})},r.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},r.t=function(t,a){if(1&a&&(t=r(t)),8&a)return t;if(4&a&&"object"==typeof t&&t&&t.__esModule)return t;var i=Object.create(null);if(r.r(i),Object.defineProperty(i,"default",{enumerable:!0,value:t}),2&a&&"string"!=typeof t)for(var n in t)r.d(i,n,function(a){return t[a]}.bind(null,n));return i},r.n=function(t){var a=t&&t.__esModule?function(){return t.default}:function(){return t};return r.d(a,"a",a),a},r.o=function(t,a){return Object.prototype.hasOwnProperty.call(t,a)},r.p="";var p=window.webpackJsonp=window.webpackJsonp||[],o=p.push.bind(p);p.push=a,p=p.slice();for(var u=0;u<p.length;u++)a(p[u]);var c=o;m.push([17,0]),i()}({17:function(t,a,i){"use strict";i.r(a);var r=i(0);Object(r.a)("uk","army",i(18),i(1))},18:function(t){t.exports=JSON.parse('{"category":[{"name":"英国","link":"uk_shortcut"},{"name":"陆战武器","link":"uk_army"},{"name":"坦克","link":"uk_army#uk_army_tank"}],"model":"“马蒂尔达”步兵坦克","description":"<h6>综述：</h6><p>步兵坦克是英军在二战中用作为步兵提供战斗支援和保护的一种坦克，它要求其装甲防护能抵挡反坦克器械和机枪的射击，但对行进速度要求不高，能够跟上步兵的战斗进攻速度即可。“马蒂尔达”是英军最早研制的一种步兵坦克型号，主要有Ⅰ型（A11）和Ⅱ型（A12）两种型号，Ⅰ型（A11）属轻型坦克，重量轻，火力弱，但有较好的防御能力；Ⅱ型（A12）属中型坦克，动力、火力和防护都有较大提升。Ⅰ型坦克在二战早期装备了英国远征军，在法国战场参加了实战，但战况并不理想。Ⅱ型坦克则从二战开始参战直到1942年北非战役；该型除装备英军外，还装备了澳大利亚军队，也有部分给了苏军。</p><p>“马蒂尔达”Ⅱ型坦克派生过如扫雷、推土、喷火等多种变形坦克，它在二战期间共生产了近3000辆。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}1940年法国北部战场阿拉斯反击战中，隶属英国第4皇家坦克团的一辆马蒂尔达Ⅰ型（A11）步兵坦克。注意坦克炮塔侧面有一观察镜，英军称之为“眼睛”，这是源自第一次世界大战时的灵感所设计。{{image}}imgs/uk/army/uk_army_tankmt_11.jpg{{text}}英国远征军第7皇家坦克团的一辆马蒂尔达Ⅰ型（A11）步兵坦克，坦克车体和炮塔涂有深浅不同的绿色伪装。该坦克在法国一次战斗中因失去战斗力而被英军丢弃。{{image}}imgs/uk/army/uk_army_tankmt_12.jpg{{text}}1940年夏季，在英国本土，一辆不明单位的马蒂尔达Ⅰ型（A11）步兵坦克。{{image}}imgs/uk/army/uk_army_tankmt_13.jpg","description":"<h6>马蒂尔达Ⅰ型（A11）步兵坦克</h6><p>该型坦克主要用作步兵进攻时的近距离支援，在二战前（1939年）已完成研制，一共生产了139辆。在二战早期，该坦克对敌方的反坦克火力有一定防护能力，但自身火力弱，在战场上很难为步兵的进攻提供火力掩护。</p><p>坦克参数：</p><p>车长：4.85m，车宽：2.28m, 车高：1.86m，车重：11.18t，乘员：2人；</p><p>最高车速：12.8km/h，最大行程：129km；</p><p>装甲厚度：10-60mm；武器装备：一挺7.7mm口径机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>车体矮小，小炮塔配短身管机枪。</li><li>悬挂装置每侧有小口径负重轮4对共8个。</li><li>炮塔侧钭挂着1个观察镜（眼睛）。</li></ol></span>","caption":""},{"image":"{{text}}1941年北非战场，隶属英国第7装甲团的一辆马蒂尔达Ⅱ型（A12）步兵坦克。这辆编号为6970坦克别名为“战场女王”，此辆坦克在1941年6月的“战斧行动”中被德军缴获。{{image}}imgs/uk/army/uk_army_tankmt_21.jpg{{text}}1940年5月，在法国战场，隶属英国远征军第7皇家坦克团的一辆马蒂尔达Ⅱ型（A12）步兵坦克，坦克车体涂有的白色方块象征坦克的国籍。{{image}}imgs/uk/army/uk_army_tankmt_22.jpg{{text}}1941年至1942年间，在莫斯科前线作战的苏联某坦克部队一辆马蒂尔达Ⅱ型（A12）步兵坦克。坦克原来的英军伪装色与英文标识已被复盖。{{image}}imgs/uk/army/uk_army_tankmt_23.jpg","description":"<h6>马蒂尔达Ⅱ型（A12）步兵坦克</h6><p>该型坦克在Ⅰ型的基础上作了很大改进，装甲厚度提高，悬挂系统加装了装甲防护，换装了约40mm口径的火炮（炮弹2磅，也称2磅火炮），车速与行程也提高近一倍。到1943年止，该型坦克一共生产了2987辆，主要装备英军，也装备了在非洲战场的澳大利亚装甲部队，它们参加了非洲厄立特时亚、新几内亚和北非沙漠的战斗。</p><p>坦克参数：</p><p>车长：5.6m，车宽：2.6m, 车高：2.5m，车重：近27t，乘员：4人；</p><p>最高车速：24km/h，最大行程：255km；</p><p>装甲厚度：13-78mm；武器装备：一挺2磅火炮，一挺7.92mm口径的机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>车体与炮塔较大。</li><li>悬挂装置每侧都装有基本全复盖的防护装甲。</li><li>炮塔安装有1门火炮和1挺机枪。</li></ol></span>","caption":""}],"part2title":"战场上的马蒂尔达步兵坦克","part2description":"<p>二战早期，德军入侵西欧，马蒂尔达Ⅰ型与Ⅱ型步兵坦克都随英国远征军参加了战斗，在法国北部战场有名的阿拉斯反击战中，初期也使德军感到压力，但由于补给不足，后最终被德军隆美尔的第7装甲师击溃，英国第一集团军坦克旅两个营的马蒂尔达Ⅰ型坦克基本损失殆尽。1941年，装备了马蒂尔达Ⅱ型步兵坦克的英军和澳军在非洲战场与意大利军和德军作战，1941年5月，在利比亚与埃及边境地带，英军第7装甲旅皇家第4坦克团的马蒂尔达Ⅱ型坦克，在代号为“短促”的反击行动早期突击哈尔法亚隘口的战斗中，面对意军的反坦克炮，马蒂尔达Ⅱ型坦克厚重的装甲防护发挥了作用，战斗中虽损失了7辆坦克，但最终打垮了意军，攻下了哈尔法亚隘口；马蒂尔达Ⅱ型步兵坦克获得了“沙漠女皇”的称号。但后来在与德军交战中，面对隆美尔非洲军团的88炮和坦克重炮，马蒂尔达Ⅱ型坦克的装甲则失去了优势，在一次“战斧”行动中，英军就损失了64辆马蒂尔达Ⅱ型坦克。1942年中期后，二战战场上就基本失去了马蒂尔达步兵坦克的身影。</p>","part2content":[{"image":"imgs/uk/army/uk_army_tankmt_31.jpg","description":"1939-1940年，法国北部战场，一辆马蒂尔达Ⅱ型步兵坦克正在掩护英军步兵前进。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_32.jpg","description":"1941年法国战场，英军正在对一辆马蒂尔达Ⅰ型步兵坦克进行检修。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_33.jpg","description":"1941年非洲战场，英军的马蒂尔达Ⅱ型步兵坦克正在集结准备对意军发动攻击。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_34.jpg","description":"1941年1月，非洲战场，英军对一辆准备投入战斗的马蒂尔达Ⅱ型步兵坦克进行伪装。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_35.jpg","description":"1941年非洲战场，英军第4皇家坦克团B中队的马蒂尔达Ⅱ型步兵坦克正在向战场进发。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_36.jpg","description":"1941年非洲战场，一辆英军的马蒂尔达Ⅱ型步兵坦克在与意军作战后凯旋而归，坦克上还插着一面缴获的意大利国旗。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_37.jpg","description":"1941年非洲战场，英军对一辆在伪装网内的马蒂尔达Ⅱ型步兵坦克进行检修。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_38.jpg","description":"1942年苏联战场，苏联西南方面军一辆马蒂尔达Ⅱ型步兵坦克正在与德军作战。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_39.jpg","description":"1942年5月苏联战场，苏联西南方面军第133装甲旅的马蒂尔达Ⅱ型步兵坦克正在支援苏军步兵向德军阵地进攻。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_40.jpg","description":"1942年5月苏联战场，苏军步兵在西南方面军第133装甲旅的马蒂尔达Ⅱ型步兵坦克的掩护下攻入德军阵地。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_41.jpg","description":"1941年非洲战场，一辆被德军88炮击毁的英军马蒂尔达Ⅱ型步兵坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_42.jpg","description":"1941年非洲战场，被德军第7装甲师击毁的一辆隶属英军第7皇家坦克团的马蒂尔达Ⅱ型步兵坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_43.jpg","description":"1941年非洲战场，德军驾驶着一辆缴获的英军马蒂尔达Ⅱ型步兵坦克正在行进，图左边是一辆德军的Ⅱ号坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_44.jpg","description":"在阿拉姆战场，一辆安装大胡萝卜扫雷器（具有600磅的压力）的马蒂尔达Ⅱ型步兵坦克正在进行扫雷操作。","caption":""},{"image":"imgs/uk/army/uk_army_tankmt_45.jpg","description":"在非洲战场，一辆安装蝎子扫雷器的马蒂尔达Ⅱ型步兵坦克正在行进。该扫雷器有1个独立的动力装置，可由操作员（坐在坦克车体旁）在坦克内部控制。","caption":""}]}')}});